// Package time implements the "time" template-function namespace. The
// behaviour (including error texts) mirrors the reference gomplate binary:
// the namespace is a struct whose string fields are the pre-defined layout
// constants, and whose methods are the namespace functions.
package time

import (
	"fmt"
	"strconv"
	stdstrings "strings"
	stdtime "time"
)

// Funcs is the namespace value returned by NS. The layout constants are
// fields (so `time.ANSIC` resolves to a string, and is not invocable as a
// function), everything else is a method.
type Funcs struct {
	ANSIC       string
	UnixDate    string
	RubyDate    string
	RFC822      string
	RFC822Z     string
	RFC850      string
	RFC1123     string
	RFC1123Z    string
	RFC3339     string
	RFC3339Nano string
	Kitchen     string
	Stamp       string
	StampMilli  string
	StampMicro  string
	StampNano   string
}

// NS returns the time namespace value: a pointer to a struct whose methods
// are the namespace functions and whose fields are the layout constants.
func NS() any {
	return &Funcs{
		ANSIC:       stdtime.ANSIC,
		UnixDate:    stdtime.UnixDate,
		RubyDate:    stdtime.RubyDate,
		RFC822:      stdtime.RFC822,
		RFC822Z:     stdtime.RFC822Z,
		RFC850:      stdtime.RFC850,
		RFC1123:     stdtime.RFC1123,
		RFC1123Z:    stdtime.RFC1123Z,
		RFC3339:     stdtime.RFC3339,
		RFC3339Nano: stdtime.RFC3339Nano,
		Kitchen:     stdtime.Kitchen,
		Stamp:       stdtime.Stamp,
		StampMilli:  stdtime.StampMilli,
		StampMicro:  stdtime.StampMicro,
		StampNano:   stdtime.StampNano,
	}
}

// Now returns the current local time.
func (Funcs) Now() stdtime.Time {
	return stdtime.Now()
}

// Parse parses a timestamp defined by the given layout. In the absence of a
// time zone indicator, the time is interpreted as UTC.
func (Funcs) Parse(layout, timestamp string) (stdtime.Time, error) {
	return stdtime.Parse(layout, timestamp)
}

// ParseLocal is like Parse, except that in the absence of a time zone
// indicator the timestamp is parsed in the local timezone.
func (Funcs) ParseLocal(layout, timestamp string) (stdtime.Time, error) {
	return stdtime.ParseInLocation(layout, timestamp, stdtime.Local)
}

// ParseInLocation is like Parse, except that the time is parsed in the given
// location's time zone.
func (Funcs) ParseInLocation(layout, location, timestamp string) (stdtime.Time, error) {
	loc, err := stdtime.LoadLocation(location)
	if err != nil {
		return stdtime.Time{}, err
	}
	return stdtime.ParseInLocation(layout, timestamp, loc)
}

// ParseDuration parses a duration string such as "300ms", "-1.5h" or "2h45m".
func (Funcs) ParseDuration(duration string) (stdtime.Duration, error) {
	return stdtime.ParseDuration(duration)
}

// Since returns the time elapsed since t.
func (Funcs) Since(t stdtime.Time) stdtime.Duration {
	return stdtime.Since(t)
}

// Until returns the duration until t.
func (Funcs) Until(t stdtime.Time) stdtime.Duration {
	return stdtime.Until(t)
}

// Unix returns the local Time corresponding to the given Unix time, in
// seconds since January 1, 1970 UTC. Fractional seconds may be given, but
// only when the input is a string.
func (Funcs) Unix(in any) (stdtime.Time, error) {
	sec, nsec, err := parseUnixTimestamp(in)
	if err != nil {
		return stdtime.Time{}, err
	}
	return stdtime.Unix(sec, nsec), nil
}

// ZoneName returns the local system's time zone's name.
func (Funcs) ZoneName() string {
	name, _ := stdtime.Now().Zone()
	return name
}

// ZoneOffset returns the local system's time zone offset, in seconds east of
// UTC.
func (Funcs) ZoneOffset() int {
	_, offset := stdtime.Now().Zone()
	return offset
}

// Nanosecond returns n nanoseconds as a Duration.
func (f Funcs) Nanosecond(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Nanosecond)
}

// Microsecond returns n microseconds as a Duration.
func (f Funcs) Microsecond(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Microsecond)
}

// Millisecond returns n milliseconds as a Duration.
func (f Funcs) Millisecond(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Millisecond)
}

// Second returns n seconds as a Duration.
func (f Funcs) Second(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Second)
}

// Minute returns n minutes as a Duration.
func (f Funcs) Minute(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Minute)
}

// Hour returns n hours as a Duration.
func (f Funcs) Hour(n any) (stdtime.Duration, error) {
	return f.duration(n, stdtime.Hour)
}

func (Funcs) duration(n any, unit stdtime.Duration) (stdtime.Duration, error) {
	i, err := toInt64(n)
	if err != nil {
		return 0, fmt.Errorf("expected a number: %w", err)
	}
	return stdtime.Duration(i) * unit, nil
}

// toInt64 converts its input to an int64. Strings are parsed as integers
// (base-prefix aware, so "0x10" is 16) and fall back to float parsing with
// truncation ("1.5" is 1). Floats truncate toward zero, booleans coerce to
// 0/1. Anything else is an error.
func toInt64(in any) (int64, error) {
	if s, ok := in.(string); ok {
		if i, err := strconv.ParseInt(s, 0, 64); err == nil {
			return i, nil
		}
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, fmt.Errorf("could not convert %q to int64: %w", s, err)
		}
		return int64(f), nil
	}
	switch n := in.(type) {
	case int:
		return int64(n), nil
	case int8:
		return int64(n), nil
	case int16:
		return int64(n), nil
	case int32:
		return int64(n), nil
	case int64:
		return n, nil
	case uint:
		return int64(n), nil
	case uint8:
		return int64(n), nil
	case uint16:
		return int64(n), nil
	case uint32:
		return int64(n), nil
	case uint64:
		return int64(n), nil
	case float32:
		return int64(n), nil
	case float64:
		return int64(n), nil
	case bool:
		if n {
			return 1, nil
		}
		return 0, nil
	}
	return 0, fmt.Errorf("could not convert %v to int64", in)
}

// parseUnixTimestamp splits a Unix timestamp into seconds and nanoseconds.
// Strings may contain a single '.' separating a fractional-second part, which
// is truncated/padded to 9 digits and parsed as an integer. Floating-point
// input is rejected; any other non-string input is treated leniently as a
// whole number of seconds (non-numeric inputs yield 0).
func parseUnixTimestamp(in any) (sec, nsec int64, err error) {
	switch v := in.(type) {
	case string:
		parts := stdstrings.Split(v, ".")
		if len(parts) > 2 {
			return 0, 0, fmt.Errorf("can not parse '%s' as a number - too many decimal points", v)
		}
		sec, err = strconv.ParseInt(parts[0], 0, 64)
		if err != nil {
			return 0, 0, err
		}
		if len(parts) == 2 {
			frac := parts[1]
			if len(frac) > 9 {
				frac = frac[:9]
			}
			for len(frac) < 9 {
				frac += "0"
			}
			nsec, err = strconv.ParseInt(frac, 0, 64)
			if err != nil {
				return 0, 0, err
			}
		}
		return sec, nsec, nil
	case float32:
		return 0, 0, fmt.Errorf("can not parse floating point number (%f) - use a string instead", v)
	case float64:
		return 0, 0, fmt.Errorf("can not parse floating point number (%f) - use a string instead", v)
	}
	// all other types: only integers carry a value, everything else is 0
	sec, _ = toUnixInt64(in)
	return sec, 0, nil
}

// toUnixInt64 converts integer inputs to int64; everything else yields 0.
func toUnixInt64(in any) (int64, bool) {
	switch n := in.(type) {
	case int:
		return int64(n), true
	case int8:
		return int64(n), true
	case int16:
		return int64(n), true
	case int32:
		return int64(n), true
	case int64:
		return n, true
	case uint:
		return int64(n), true
	case uint8:
		return int64(n), true
	case uint16:
		return int64(n), true
	case uint32:
		return int64(n), true
	case uint64:
		return int64(n), true
	}
	return 0, false
}

package time

import (
	"bytes"
	stdstrings "strings"
	"testing"
	"text/template"
	stdtime "time"
)

func renderData(t *testing.T, tmpl string, data map[string]any) (string, error) {
	t.Helper()
	fmap := template.FuncMap{"time": func() any { return NS() }}
	tt, err := template.New("<arg>").Option("missingkey=error").Funcs(fmap).Parse(tmpl)
	if err != nil {
		return "", err
	}
	if data == nil {
		data = map[string]any{}
	}
	data["Env"] = map[string]string{}
	var buf bytes.Buffer
	err = tt.Execute(&buf, data)
	return buf.String(), err
}

func render(t *testing.T, tmpl string) (string, error) {
	t.Helper()
	return renderData(t, tmpl, nil)
}

func TestLayouts(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		want string
	}{
		{"ANSIC", "Mon Jan _2 15:04:05 2006"},
		{"UnixDate", "Mon Jan _2 15:04:05 MST 2006"},
		{"RubyDate", "Mon Jan 02 15:04:05 -0700 2006"},
		{"RFC822", "02 Jan 06 15:04 MST"},
		{"RFC822Z", "02 Jan 06 15:04 -0700"},
		{"RFC850", "Monday, 02-Jan-06 15:04:05 MST"},
		{"RFC1123", "Mon, 02 Jan 2006 15:04:05 MST"},
		{"RFC1123Z", "Mon, 02 Jan 2006 15:04:05 -0700"},
		{"RFC3339", "2006-01-02T15:04:05Z07:00"},
		{"RFC3339Nano", "2006-01-02T15:04:05.999999999Z07:00"},
		{"Kitchen", "3:04PM"},
		{"Stamp", "Jan _2 15:04:05"},
		{"StampMilli", "Jan _2 15:04:05.000"},
		{"StampMicro", "Jan _2 15:04:05.000000"},
		{"StampNano", "Jan _2 15:04:05.000000000"},
	}
	for _, c := range cases {
		c := c
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			out, err := render(t, "{{ time."+c.name+" }}")
