func TestReferenceByteForByte(t *testing.T) {
	tmpls := []string{
		// constants
		`{{ time.ANSIC }}`, `{{ time.UnixDate }}`, `{{ time.RubyDate }}`,
		`{{ time.RFC822 }}`, `{{ time.RFC822Z }}`, `{{ time.RFC850 }}`,
		`{{ time.RFC1123 }}`, `{{ time.RFC1123Z }}`, `{{ time.RFC3339 }}`,
		`{{ time.RFC3339Nano }}`, `{{ time.Kitchen }}`, `{{ time.Stamp }}`,
		`{{ time.StampMilli }}`, `{{ time.StampMicro }}`, `{{ time.StampNano }}`,
		// doc examples (deterministic ones)
		`{{ (time.Parse "2006-01-02" "1993-10-23").Format "Monday January 2, 2006 MST" }}`,
		`{{ (time.Unix 42).UTC.Format time.Stamp}}`,
		`{{ (time.Unix "123456.789").UTC.Format time.StampMilli}}`,
		`{{ time.ParseDuration "2h30m" }}`,
		// parse variants
		`{{ "1993-10-23" | time.Parse "2006-01-02" }}`,
		`{{ (time.Parse time.RFC3339 "2020-06-01T10:00:00+02:00").Format "15:04 MST" }}`,
		`{{ (time.ParseLocal time.RFC3339 "2020-06-01T10:00:00+02:00").Format "15:04 MST" }}`,
		`{{ (time.ParseLocal "2006-01-02" "1993-10-23").Format "MST" }}`,
		`{{ (time.ParseInLocation time.Kitchen "UTC" "6:00AM").Format "15:04 MST" }}`,
		// unix variants
		`{{ time.Unix 42 }}`,
		`{{ time.Unix "0x10" }}`,
		`{{ time.Unix "010" }}`,
		`{{ time.Unix "0b101" }}`,
		`{{ (time.Unix "-42.5").UTC.Format time.StampMilli }}`,
		`{{ (time.Unix "-0.5").UTC.Format time.StampMilli }}`,
		`{{ (time.Unix "42.").UTC.Format time.Stamp }}`,
		`{{ (time.Unix "42.123456789123").UTC.Format time.StampNano }}`,
		`{{ time.Unix "9223372036854775807" }}`,
		`{{ time.Unix true }}`,
		// durations
		`{{ time.Nanosecond 1 }}`, `{{ time.Microsecond 1500 }}`,
		`{{ time.Millisecond 1500 }}`, `{{ time.Second 1 }}`,
		`{{ time.Minute 2 }}`, `{{ time.Hour 2 }}`,
		`{{ time.Second -5 }}`, `{{ time.Second 2.9 }}`, `{{ time.Second -2.7 }}`,
		`{{ time.Second "3" }}`, `{{ time.Second "1.5" }}`, `{{ time.Second "0x10" }}`,
		`{{ time.Second "0b101" }}`, `{{ time.Second "09" }}`, `{{ time.Second "1_000" }}`,
		`{{ time.Second "5e2" }}`, `{{ time.Nanosecond "1e3" }}`,
		`{{ time.Second true }}`, `{{ time.Second false }}`,
		`{{ time.Second "NaN" }}`, `{{ time.Second "+Inf" }}`, `{{ time.Second "-Inf" }}`,
