func TestReferenceErrorTexts(t *testing.T) {
	tmpls := []string{
		`{{ time.Parse "2006-01-02" "bad" }}`,
		`{{ time.Parse time.RFC3339 "1993-10-23" }}`,
		`{{ time.ParseDuration "bad" }}`,
