		`{{ time.Unix 42.9 }}`,
		`{{ time.Unix "abc" }}`,
		`{{ time.Unix "" }}`,
		`{{ time.Unix ".5" }}`,
		`{{ time.Unix " 42 " }}`,
		`{{ time.Unix "1e3" }}`,
		`{{ time.Unix "42.5.6" }}`,
		`{{ time.Unix "42.abc" }}`,
		`{{ time.Unix "42.12e3" }}`,
		`{{ time.Unix "42.0789" }}`,
		`{{ time.Second "abc" }}`,
		`{{ time.Second " 5" }}`,
