		`{{ time.ANSIC "x" }}`,
		`{{ time.Second }}`,
		`{{ time.Second 1 2 }}`,
		`{{ time.Parse "a" "b" "c" }}`,
	}
	for _, tmpl := range tmpls {
		_, err := render(t, tmpl)
		if err == nil {
			t.Fatalf("%s: expected error", tmpl)
		}
		cmd := exec.Command("/workspace/executable", "-i", tmpl)
		refOut, rerr := cmd.Output()
		_ = refOut
		if rerr == nil {
			t.Fatalf("%s: reference did not fail", tmpl)
		}
		exitErr, ok := rerr.(*exec.ExitError)
		if !ok {
			t.Fatalf("%s: unexpected reference error type: %v", tmpl, rerr)
		}
		refMsg := string(exitErr.Stderr)
		// extract text after "error calling X: " or compare raw template msg
		idx := stdstrings.LastIndex(refMsg, "err\":\"")
