		refErr := stdstrings.TrimSuffix(refMsg[idx+6:], "\"}\n")
		refErr = stdstrings.ReplaceAll(refErr, `\"`, `"`)
		// my error text is the part after the binary's "renderTemplate: failed to render template <arg>: " prefix
		prefix := "renderTemplate: failed to render template <arg>: "
		if !stdstrings.HasPrefix(refErr, prefix) {
			t.Fatalf("%s: unexpected ref err shape %q", tmpl, refErr)
		}
		refErr = stdstrings.TrimPrefix(refErr, prefix)
		if err.Error() != refErr {
			t.Errorf("%s:\n  mine: %q\n  ref:  %q", tmpl, err.Error(), refErr)
		}
	}
}
